CREATE OR REPLACE FUNCTION calculate_composite_allocation_score(p_match_id text)
RETURNS numeric AS $$
DECLARE
    v_status_medical numeric;
    v_wait_time_days numeric;
    v_r_wait numeric;
    v_s_urgency numeric;
    v_i_abo numeric;
    v_s_mismatch numeric;
    v_s_immune numeric;
    v_egs_val real;
    v_donor_age numeric;
    v_composite numeric;
BEGIN
    -- Get medical urgency status value
    SELECT CASE 
        WHEN UPPER(c.med_urgency) = 'STATUS 1A' THEN 5
        WHEN UPPER(c.med_urgency) = 'STATUS 1B' THEN 4
        WHEN c.med_urgency = '2' THEN 3
        WHEN c.med_urgency = '3' THEN 2
        ELSE 1
    END
    INTO v_status_medical
    FROM transplant_matching tm
    JOIN clinical c ON tm.recip_ref_reg = c.clin_recip_registry
    WHERE tm.match_rec_registry = p_match_id;

    -- Get wait time in days (extract number before "days")
    SELECT CAST(SUBSTRING(c.wait_time FROM '^[0-9]+') AS numeric)
    INTO v_wait_time_days
    FROM transplant_matching tm
    JOIN clinical c ON tm.recip_ref_reg = c.clin_recip_registry
    WHERE tm.match_rec_registry = p_match_id;

    -- Recipient Wait Time Ratio
    v_r_wait := v_wait_time_days / 365.0;

    -- Patient Urgency Score
    v_s_urgency := 0.7 * v_status_medical + 0.3 * v_r_wait;

    -- ABO Blood Type Compatibility
    SELECT CASE 
        WHEN UPPER(cm.blood_compat) = 'COMPATIBLE' THEN 1
        ELSE 0
    END
    INTO v_i_abo
    FROM compatibility_metrics cm
    WHERE cm.match_comp_registry = p_match_id;

    -- HLA Mismatch Score
    SELECT cm.hla_mis_count::numeric
    INTO v_s_mismatch
    FROM compatibility_metrics cm
    WHERE cm.match_comp_registry = p_match_id;

    -- Immunological Compatibility Score
    v_s_immune := 0.6 * v_i_abo + 0.4 * (1 - v_s_mismatch / 6.0);

    -- EGS Score from risk_evaluation
    SELECT re.egs_val
    INTO v_egs_val
    FROM risk_evaluation re
    WHERE re.risk_eval_registry = p_match_id;

    -- Handle NULL EGS - use calculated version if available
    IF v_egs_val IS NULL THEN
        -- Get donor age
        SELECT CAST(SPLIT_PART(d.age_count, ' ', 1) AS numeric)
        INTO v_donor_age
        FROM demographics d
        JOIN transplant_matching tm ON d.contrib_registry = tm.donor_ref_reg
        WHERE tm.match_rec_registry = p_match_id;

        -- Calculate EGS using formula: 1/(1+exp(-(-0.5 + 1.5*S_immune - 0.02*Age_donor)))
        v_egs_val := 1.0 / (1.0 + exp(-(-0.5 + 1.5 * v_s_immune - 0.02 * v_donor_age)));
    END IF;

    -- Composite Allocation Score
    v_composite := 0.5 * v_s_urgency + 0.25 * v_s_immune + 0.25 * v_egs_val;

    RETURN ROUND(CAST(v_composite AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

